import {
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Mesh,
  Group,
  Color
} from 'three/webgpu';
import { uv, vec2, vec4, texture } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group: THREEGroup, Mesh: THREEMesh, Color: THREEColor } = ctx.THREE;

  // 1. Root group and layout container
  const group = new THREEGroup();
  const cleanupTasks = [];

  // 2. Palette and configuration parameters
  const colorSpec = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const inkColor = new THREEColor(colorSpec.ink);
  const paperColor = new THREEColor(colorSpec.paper);
  const accentColor = new THREEColor(colorSpec.accent);
  const surfaceColor = new THREEColor(colorSpec.surface);

  // 3. Stage Backdrop Plane (Engineered Vertical Gradient with subtle grain)
  // Dimensions chosen to gracefully cover the backdrop space of the label card
  const bgGeo = new PlaneGeometry(2.5, 1.5);
  const bgMat = new MeshBasicNodeMaterial({ transparent: true });

  // Custom TSL Shader to draw an engineered gradient with procedural grain overlay
  const uvNode = uv();
  const gradient = uvNode.y; // simple linear vertical gradient Node
  const baseColor = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b), vec3(inkColor.r, inkColor.g, inkColor.b), gradient);

  // Subtle structural procedural grain pattern node
  const grainVal = fract(sin(dot(uvNode.xy, vec2(12.9898, 78.233))) * 43758.5453);
  const finalColor = mix(baseColor, vec3(paperColor.r, paperColor.g, paperColor.b), grainVal.mul(0.04));

  bgMat.colorNode = vec4(finalColor, 0.95);

  const bgMesh = new THREEMesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -0.02);
  group.add(bgMesh);

  // Optional External Sprite Texture Overlay
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // Atlas source mapping (0, 0, 512, 320) -> Normalize UV mapping across texture space 512x512
      tex.repeat.set(512 / 512, 320 / 512);
      tex.offset.set(0 / 512, (512 - 320) / 512);

      const spriteMat = new MeshBasicNodeMaterial({
        map: tex,
        transparent: true,
        opacity: 0.35
      });
      const spriteGeo = new PlaneGeometry(2.5, 1.5);
      const spriteMesh = new THREEMesh(spriteGeo, spriteMat);
      spriteMesh.position.set(0, 0, -0.01);
      group.add(spriteMesh);
    });
  }

  // 4. Highlight Border Accent (Machined-edge frame look)
  const borderGeo = new PlaneGeometry(2.52, 1.52);
  const borderMat = new MeshBasicNodeMaterial({ 
    color: accentColor, 
    wireframe: true,
    transparent: true,
    opacity: 0.7
  });
  const borderMesh = new THREEMesh(borderGeo, borderMat);
  borderMesh.position.set(0, 0, -0.03);
  group.add(borderMesh);

  // 5. Render Verbatim Texts
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textContainer = new THREEGroup();
  textContainer.position.set(0, 0, 0.02);
  group.add(textContainer);

  let labelStr = "Pricing 2";
  for (const item of textItems) {
    if (item.role === 'headline' || item.text) {
      labelStr = item.text;
      break;
    }
  }

  // Display-size serif style rendering inside the atlas
  const mainLabel = ctx.fontAtlas.createText(labelStr, {
    fontSize: 39,
    color: paperColor,
    align: 'center'
  });
  // Adjust position and local space scale down to viewport scene units
  mainLabel.position.set(0, 0, 0);
  textContainer.add(mainLabel);

  // 6. Weight-settle entrance animation on mount
  group.scale.set(0.01, 0.01, 0.01);
  const settleTl = gsap.timeline();
  settleTl.to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: "power4.out"
  });

  // 7. Cleanup and dispose bindings
  group.userData = {
    handlers: {},
    cleanup: () => {
      settleTl.kill();
      bgGeo.dispose();
      bgMat.dispose();
      borderGeo.dispose();
      borderMat.dispose();
    }
  };

  return group;
}
